#include <stdint.h>
#include <stdio.h>
#include "app_time.h"
#include "udp_telemetry.h"
#include "task_encoder_cal.h"
#define ENCODER_DISTANCE_STRAIGHT_ROUNDTRIP_TEST_MODE 1
#define TOL 15
typedef enum{WAIT,ARM,FWD,FSETTLE,PAUSE,REV,RSETTLE,DONE,ABORT} State;
typedef struct {uint8_t valid,aborted;int32_t forwardStartLeft,forwardStartRight,forwardEndLeft,forwardEndRight,targetLeft,targetRight,reverseStartLeft,reverseStartRight,reverseEndLeft,reverseEndRight,reverseTotalLeft,reverseTotalRight,errorLeft,errorRight,errorLeftPermille,errorRightPermille;uint32_t forwardDurationMs,reverseDurationMs,forwardEncoderFrames,reverseEncoderFrames,leftTargetReachedMs,rightTargetReachedMs;uint8_t forwardStartSeq,forwardEndSeq,reverseStartSeq,reverseEndSeq;uint32_t badChecksum,badFrame;} RoundtripResult;
static State st;static uint32_t tick,base,idx,revStart,revValidStart,leftHit,rightHit,doneMs,lastSummary;static int32_t forwardValidStart;static RoundtripResult g_roundtripResult;
static void publish(const char *event){char b[768];UdpTelemetryPublishCal((snprintf(b,sizeof(b),"ROUNDTRIP event=%s target_l=%ld target_r=%ld reverse_l=%ld reverse_r=%ld error_l=%ld error_r=%ld error_l_permille=%ld error_r_permille=%ld forward_ms=%u reverse_ms=%u forward_frames=%u reverse_frames=%u left_reached_ms=%u right_reached_ms=%u f_start_seq=%u f_end_seq=%u r_start_seq=%u r_end_seq=%u valid=%u",event,(long)g_roundtripResult.targetLeft,(long)g_roundtripResult.targetRight,(long)g_roundtripResult.reverseTotalLeft,(long)g_roundtripResult.reverseTotalRight,(long)g_roundtripResult.errorLeft,(long)g_roundtripResult.errorRight,(long)g_roundtripResult.errorLeftPermille,(long)g_roundtripResult.errorRightPermille,(unsigned)g_roundtripResult.forwardDurationMs,(unsigned)g_roundtripResult.reverseDurationMs,(unsigned)g_roundtripResult.forwardEncoderFrames,(unsigned)g_roundtripResult.reverseEncoderFrames,(unsigned)g_roundtripResult.leftTargetReachedMs,(unsigned)g_roundtripResult.rightTargetReachedMs,g_roundtripResult.forwardStartSeq,g_roundtripResult.forwardEndSeq,g_roundtripResult.reverseStartSeq,g_roundtripResult.reverseEndSeq,g_roundtripResult.valid),b));}
void EncoderCalInit(void){st=WAIT;tick=base=idx=0;leftHit=rightHit=0;g_roundtripResult=(RoundtripResult){0};publish("BOOT");publish("WAIT_ENCODER");}
int EncoderCalIsActive(void){return ENCODER_DISTANCE_STRAIGHT_ROUNDTRIP_TEST_MODE;}
void EncoderCalStep(uint32_t now,int*l,int*r){UdpEncoderTelemetryState e;uint32_t m=AppTicksToMs(now);*l=*r=0;UdpTelemetryReadEncoder(&e);if((st==FWD||st==REV)&&e.validCount&&m-e.lastRxMs>200){g_roundtripResult.aborted=1;st=ABORT;publish("ABORT_ENCODER_RX_TIMEOUT");return;}if(st==WAIT){if(!base)base=e.validCount;if(e.validCount-base>=20&&m-e.lastRxMs<=100){st=ARM;tick=m;publish("ENCODER_READY");}return;}if(st==ARM){if(m-tick>=5000){st=FWD;tick=m;g_roundtripResult.forwardStartLeft=e.totalLeft;g_roundtripResult.forwardStartRight=e.totalRight;g_roundtripResult.forwardStartSeq=e.sequence;forwardValidStart=e.validCount;g_roundtripResult.forwardDurationMs=1200;publish("FORWARD_START");}return;}if(st==FWD){*l=*r=100;if(m-tick>=1200){st=FSETTLE;tick=m;*l=*r=0;publish("FORWARD_STOP");}return;}if(st==FSETTLE){if(m-tick>=800){g_roundtripResult.forwardEndLeft=e.totalLeft;g_roundtripResult.forwardEndRight=e.totalRight;g_roundtripResult.forwardEndSeq=e.sequence;g_roundtripResult.targetLeft=e.totalLeft-g_roundtripResult.forwardStartLeft;g_roundtripResult.targetRight=e.totalRight-g_roundtripResult.forwardStartRight;g_roundtripResult.forwardEncoderFrames=e.validCount-forwardValidStart;publish("FORWARD_DONE");st=PAUSE;tick=m;}}else if(st==PAUSE){if(m-tick>=300){st=REV;tick=m;revStart=m;revValidStart=e.validCount;g_roundtripResult.reverseStartLeft=e.totalLeft;g_roundtripResult.reverseStartRight=e.totalRight;g_roundtripResult.reverseStartSeq=e.sequence;publish("REVERSE_START");}}else if(st==REV){int32_t dl=e.totalLeft-g_roundtripResult.reverseStartLeft,dr=e.totalRight-g_roundtripResult.reverseStartRight;*l=(dl<=-(g_roundtripResult.targetLeft-TOL))?0:-100;*r=(dr<=-(g_roundtripResult.targetRight-TOL))?0:-100;if(dl>50||dr>50){g_roundtripResult.aborted=1;st=ABORT;publish("ABORT_DIRECTION_WRONG");return;}if(*l==0&&!leftHit){leftHit=m-revStart;g_roundtripResult.leftTargetReachedMs=leftHit;}if(*r==0&&!rightHit){rightHit=m-revStart;g_roundtripResult.rightTargetReachedMs=rightHit;}if(*l==0&&*r==0){g_roundtripResult.reverseDurationMs=m-revStart;st=RSETTLE;tick=m;publish("REVERSE_STOP");}}else if(st==RSETTLE){if(m-tick>=800){g_roundtripResult.reverseEndLeft=e.totalLeft;g_roundtripResult.reverseEndRight=e.totalRight;g_roundtripResult.reverseEndSeq=e.sequence;g_roundtripResult.reverseTotalLeft=e.totalLeft-g_roundtripResult.reverseStartLeft;g_roundtripResult.reverseTotalRight=e.totalRight-g_roundtripResult.reverseStartRight;g_roundtripResult.reverseEncoderFrames=e.validCount-revValidStart;g_roundtripResult.errorLeft=g_roundtripResult.targetLeft+g_roundtripResult.reverseTotalLeft;g_roundtripResult.errorRight=g_roundtripResult.targetRight+g_roundtripResult.reverseTotalRight;g_roundtripResult.errorLeftPermille=g_roundtripResult.targetLeft?g_roundtripResult.errorLeft*1000/g_roundtripResult.targetLeft:0;g_roundtripResult.errorRightPermille=g_roundtripResult.targetRight?g_roundtripResult.errorRight*1000/g_roundtripResult.targetRight:0;g_roundtripResult.valid=1;st=DONE;doneMs=m;lastSummary=m;publish("RESULT");}}else if(st==DONE){if(m-lastSummary>=1000){lastSummary=m;publish("SUMMARY");}}}
